  const fill = marks.append("path").attr("fill", d =&gt; d.colour).attr("fill-opacity", 0.2)
  const outline = marks.append("path").attr("fill", "none").attr("stroke", d =&gt; d.colour).attr("stroke-width", 2)
  const meanLine = marks.append("line").attr("y1", 0).attr("stroke", d =&gt; d.colour).attr("stroke-dasharray", "4,3")
