    views.forEach((v, i) =&gt; buttons[i].classList.toggle("sb-off", v !== view))
    caption.textContent = fixedViews ? captions[0] : captions[views.indexOf(view)]
    axisLabel.text(view.axis)
    dAxisLabel.text(diffView.axis)
    const x = d3.scaleLinear()
      .domain([Math.min(0, d3.min(scales, s =&gt; view.f(s, s.min))), d3.max(scales, s =&gt; view.f(s, s.max))]).nice()
