    move(capLo).attr("x1", s =&gt; at(s, s.min)).attr("x2", s =&gt; at(s, s.min))
    move(capHi).attr("x1", s =&gt; at(s, s.max)).attr("x2", s =&gt; at(s, s.max))
    move(outline).attr("d", d =&gt; `M${points(d).join("L")}`)
