      update()
    }})
    g.panel.style.setProperty("--sb", g.colour)
  }
  dButtons.querySelector(".sb-clear").onclick = () =&gt; {
    groups.forEach(g =&gt; g.store.clear())
    groups.forEach(g =&gt; g.panel.refresh())
