Using a SMD calculator like the one below, we can calculate the SMD for this study. The calculator starts with this study. The Four studies button loads four hypothetical studies instead, to show that it can calculate the effect sizes of many studies at once, as a meta-analyst would, and This study switches back. As you can see, something might be off in the example: a SMD greater than 3, in a study with 64 participants per group, is far outside the range that sampling error can produce unless the true effect is itself enormous (Section 8.2).

viewof smdInput = {
  const fields = [["study", "Study"], ["m1", "Group 1 mean"], ["sd1", "Group 1 SD"], ["n1", "Group 1 n"], ["m2", "Group 2 mean"], ["sd2", "Group 2 SD"], ["n2", "Group 2 n"]]
  // the study in the table above, and a set of four hypothetical studies to show several at once
  const examples = {
    "This study": [["Example", 11.2, 4.9, 64, 25.1, 4.1, 64]],
    "Four studies": [["A", 22.1, 5.2, 40, 24.3, 5.5, 41], ["B", 3.8, 1.1, 25, 4.4, 1.2, 25], ["C", 14.2, 0.9, 64, 17.1, 1.0, 64], ["D", 3.6, 1.2, 10, 4.9, 1.3, 10]]
  }
  const body = html`&lt;tbody&gt;&lt;/tbody&gt;`
  const addRow = (values = []) =&gt; {
    const tr = html`&lt;tr&gt;&lt;/tr&gt;`
    tr.inputs = fields.map(([key, label], j) =&gt; {
      const input = html`&lt;input type="text" class="form-control form-control-sm" inputmode="${j === 0 ? "text" : "decimal"}" aria-label="${label}"&gt;`
      input.value = values[j] ?? ""
      input.onpaste = e =&gt; paste(e, tr, j)
      return input
    })
    const remove = html`&lt;button class="btn btn-sm smd-remove" title="Remove this row" aria-label="Remove this row"&gt;×&lt;/button&gt;`
    remove.onclick = () =&gt; { tr.remove(); if (body.children.length === 0) addRow() }
    tr.append(...tr.inputs.map(input =&gt; html`&lt;td&gt;${input}&lt;/td&gt;`), html`&lt;td&gt;${remove}&lt;/td&gt;`)
    body.append(tr)
    return tr
  }
  // a block of cells copied from a spreadsheet (tab-separated) or typed as comma-separated values fills the grid
  // from the cell it was pasted into, adding rows as needed. a single value is pasted as normal
  const paste = (e, tr, j) =&gt; {
    const text = e.clipboardData.getData("text").replace(/\r/g, "").replace(/\n+$/, "")
    if (!/[\t\n,]/.test(text)) return
    e.preventDefault()
    let row = tr
    for (const line of text.split("\n")) {
      const cells = line.split(line.includes("\t") ? "\t" : ",")
      cells.forEach((cell, k) =&gt; { if (j + k &lt; fields.length) row.inputs[j + k].value = cell.trim() })
      row = row.nextElementSibling ?? addRow()
    }
    // a trailing empty row that was only added for the next line is removed again
    if (row !== tr && row.inputs.every(input =&gt; input.value === "") && row.previousElementSibling) row.remove()
  }
  const load = rows =&gt; { body.replaceChildren(); rows.forEach(values =&gt; addRow(values)) }
  load(examples["This study"])
  const exampleButtons = Object.entries(examples).map(([name, rows]) =&gt; {
    const button = html`&lt;button class="btn btn-quarto"&gt;${name}&lt;/button&gt;`
    button.onclick = () =&gt; load(rows)
    return button
  })
  const measure = html`&lt;select class="form-select form-select-sm smd-measure" aria-label="Effect size"&gt;
    &lt;option value="g"&gt;Cohen's d with Hedges' correction&lt;/option&gt;
    &lt;option value="d"&gt;Cohen's d without Hedges' correction&lt;/option&gt;
  &lt;/select&gt;`
  const add = html`&lt;button class="btn btn-quarto"&gt;Add row&lt;/button&gt;`
  const clear = html`&lt;button class="btn btn-quarto"&gt;Clear all&lt;/button&gt;`
  const run = html`&lt;button class="btn btn-quarto"&gt;Calculate SMDs&lt;/button&gt;`
  add.onclick = () =&gt; addRow().inputs[0].focus()
  clear.onclick = () =&gt; { body.replaceChildren(); addRow().inputs[0].focus() }
  const view = html`&lt;div&gt;
    &lt;div class="sb-buttons sc-examples smd-examples"&gt;&lt;span&gt;Examples:&lt;/span&gt;${exampleButtons}&lt;/div&gt;
    &lt;div class="table-responsive"&gt;&lt;table class="table table-sm smd-grid"&gt;
      &lt;thead&gt;
        &lt;tr&gt;&lt;th rowspan="2"&gt;Study&lt;/th&gt;&lt;th colspan="3"&gt;Group 1 (e.g., intervention)&lt;/th&gt;&lt;th colspan="3"&gt;Group 2 (e.g., control)&lt;/th&gt;&lt;th rowspan="2"&gt;&lt;/th&gt;&lt;/tr&gt;
        &lt;tr&gt;&lt;th&gt;&lt;em&gt;M&lt;/em&gt;&lt;/th&gt;&lt;th&gt;&lt;em&gt;SD&lt;/em&gt;&lt;/th&gt;&lt;th&gt;&lt;em&gt;n&lt;/em&gt;&lt;/th&gt;&lt;th&gt;&lt;em&gt;M&lt;/em&gt;&lt;/th&gt;&lt;th&gt;&lt;em&gt;SD&lt;/em&gt;&lt;/th&gt;&lt;th&gt;&lt;em&gt;n&lt;/em&gt;&lt;/th&gt;&lt;/tr&gt;
      &lt;/thead&gt;
      ${body}
    &lt;/table&gt;&lt;/div&gt;
    &lt;div class="smd-controls"&gt;&lt;label class="sc-label"&gt;Effect size&lt;/label&gt;${measure}&lt;/div&gt;
    &lt;div class="sb-buttons"&gt;${add}${clear}${run}&lt;/div&gt;
  &lt;/div&gt;`
  // the value only changes when the calculate button is clicked
  view.value = {runs: 0}
  run.onclick = () =&gt; {
    const rows = [...body.children].map(tr =&gt; Object.fromEntries(fields.map(([key], j) =&gt; [key, tr.inputs[j].value.trim()])))
    view.value = {runs: view.value.runs + 1, rows, correct: measure.value === "g"}
    view.dispatchEvent(new Event("input", {bubbles: true}))
  }
  return view
}







