function smdChecked(rows) {
  // reads the values in each row of the grid. rows that are entirely empty are left out. a row is only sent to R if all
  // six values are numbers, both SDs are above zero, and both sample sizes are whole numbers of at least 2
  return rows.map((r, i) =&gt; ({...r, row: i + 1}))
    .filter(r =&gt; Object.values(r).some(v =&gt; v !== "" && typeof v === "string"))
    .map(r =&gt; {
      const values = Object.fromEntries(["m1", "sd1", "n1", "m2", "sd2", "n2"].map(k =&gt; [k, r[k] === "" ? NaN : Number(r[k])]))
      const problem = Object.values(values).some(v =&gt; !Number.isFinite(v)) ? "Missing or non-numeric values"
        : values.sd1 &lt;= 0 || values.sd2 &lt;= 0 ? "SDs must be above zero"
        : !Number.isInteger(values.n1) || !Number.isInteger(values.n2) || values.n1 &lt; 2 || values.n2 &lt; 2 ? "Sample sizes must be whole numbers of at least 2"
        : null
      return {...r, ...values, study: r.study || `Row ${r.row}`, valid: problem === null, problem}
    })
}

async function runEscalc(rows, correct) {
  const {webR, rVersion, version} = await webRSession.load("metafor")
  const valid = rows.filter(r =&gt; r.valid)
  const shelter = await new webR.Shelter()
  try {
    // the values are passed to R as numeric vectors, never pasted into the code
    const col = k =&gt; valid.map(r =&gt; r[k])
    const res = await shelter.evalR(`
      es &lt;- summary(escalc(measure = "SMD", m1i = m1, sd1i = sd1, n1i = n1, m2i = m2, sd2i = sd2, n2i = n2, correct = correct))
      data.frame(yi = as.numeric(es$yi), vi = as.numeric(es$vi), sei = es$sei, ci.lb = es$ci.lb, ci.ub = es$ci.ub)
    `, {env: {m1: col("m1"), sd1: col("sd1"), n1: col("n1"), m2: col("m2"), sd2: col("sd2"), n2: col("n2"), correct}})
    const out = await res.toD3()
    valid.forEach((r, i) =&gt; Object.assign(r, out[i]))
    return {rows, correct, runAt: new Date(), metaforVersion: version, rVersion}
  } finally {
    shelter.purge()
  }
}

function smdResults(run) {
  const {rows, correct, metaforVersion, rVersion} = run
  const name = correct ? "Cohen's d with Hedges' correction" : "Cohen's d without Hedges' correction"
  const valid = rows.filter(r =&gt; r.valid)
  const f2 = x =&gt; x.toFixed(2).replace("-", "−")
  // labels for the plot: the study names, with the row number added where two rows have the same name
  const counts = d3.rollup(valid, v =&gt; v.length, r =&gt; r.study)
  valid.forEach(r =&gt; { r.label = counts.get(r.study) &gt; 1 ? `${r.study} (row ${r.row})` : r.study })
  const extent = d3.extent([0, ...valid.flatMap(r =&gt; [r["ci.lb"], r["ci.ub"]])])
  const plot = Plot.plot({
    width, height: 70 + 34 * valid.length, marginLeft: Math.min(200, 20 + 7 * d3.max(valid, r =&gt; r.label.length)), marginRight: 20, marginBottom: 45,
    x: {label: `${name}, with 95% CI`, labelAnchor: "center", labelOffset: 38, grid: true, nice: true, domain: extent},
    y: {label: null, domain: valid.map(r =&gt; r.label), padding: 0.5, tickSize: 0},
    style: {fontSize: "13px"},
    marks: [
      Plot.ruleX([0], {stroke: "currentColor", strokeDasharray: "4,3", strokeOpacity: 0.6}),
      Plot.link(valid, {x1: "ci.lb", x2: "ci.ub", y1: "label", y2: "label", stroke: "#2780e3", strokeWidth: 2.5}),
      // marker area in proportion to the total sample size, as in a forest plot
      Plot.dot(valid, {x: "yi", y: "label", fill: "#2780e3", symbol: "square", r: r =&gt; 3 + 5 * Math.sqrt((r.n1 + r.n2) / d3.max(valid, v =&gt; v.n1 + v.n2))})
    ]
  })
  const body = rows.map(r =&gt; r.valid
    ? html`&lt;tr&gt;&lt;td&gt;${r.row}&lt;/td&gt;&lt;td&gt;${r.study}&lt;/td&gt;&lt;td&gt;${r.n1}&lt;/td&gt;&lt;td&gt;${r.n2}&lt;/td&gt;&lt;td&gt;${f2(r.yi)}&lt;/td&gt;&lt;td&gt;${r.sei.toFixed(3)}&lt;/td&gt;&lt;td&gt;[${f2(r["ci.lb"])}, ${f2(r["ci.ub"])}]&lt;/td&gt;&lt;/tr&gt;`
    : html`&lt;tr class="sc-row-none"&gt;&lt;td&gt;${r.row}&lt;/td&gt;&lt;td&gt;${r.study}&lt;/td&gt;&lt;td colspan="5"&gt;Not calculated: ${r.problem}&lt;/td&gt;&lt;/tr&gt;`)
  return html`&lt;div&gt;
    &lt;div class="table-responsive"&gt;&lt;table class="table table-sm smd-table"&gt;
      &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Row&lt;/th&gt;&lt;th&gt;Study&lt;/th&gt;&lt;th&gt;&lt;em&gt;n&lt;/em&gt;&lt;sub&gt;1&lt;/sub&gt;&lt;/th&gt;&lt;th&gt;&lt;em&gt;n&lt;/em&gt;&lt;sub&gt;2&lt;/sub&gt;&lt;/th&gt;&lt;th&gt;&lt;em&gt;d&lt;/em&gt;&lt;/th&gt;&lt;th&gt;&lt;em&gt;SE&lt;/em&gt;&lt;/th&gt;&lt;th&gt;95% CI&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
      &lt;tbody&gt;${body}&lt;/tbody&gt;
    &lt;/table&gt;&lt;/div&gt;
    ${plot}
    &lt;div class="sc-status"&gt;${name} for group 1 minus group 2, calculated by &lt;code&gt;escalc(measure = "SMD"${correct ? "" : ", correct = FALSE"})&lt;/code&gt; with metafor ${metaforVersion}, ${rVersion}, running in webR ${webrVersion}. The confidence intervals are the estimate ± 1.96 standard errors. The values were taken as exact, with no allowance for rounding.&lt;/div&gt;
    &lt;div class="sb-buttons sc-download"&gt;${smdDownloadButton(run)}&lt;/div&gt;
  &lt;/div&gt;`
}

function smdDownloadButton(run) {
  // the inputs, escalc's output, and the versions used, one row per row of the grid that was not empty
  const {rows, correct, runAt, metaforVersion, rVersion} = run
  const columns = ["row", "study", "m1", "sd1", "n1", "m2", "sd2", "n2", "measure", "yi", "vi", "sei", "ci_lb", "ci_ub", "status",
    "metafor_version", "r_version", "webr_version", "run_at"]
  const settings = {measure: correct ? "Cohen's d with Hedges' correction (escalc measure = SMD)" : "Cohen's d without Hedges' correction (escalc measure = SMD, correct = FALSE)", metafor_version: metaforVersion, r_version: rVersion, webr_version: webrVersion, run_at: runAt.toISOString()}
  const records = rows.map(r =&gt; r.valid
    ? {...r, ci_lb: r["ci.lb"], ci_ub: r["ci.ub"], status: "Calculated", ...settings}
    // rows that were not calculated keep the values as they were entered
    : {...r, ...Object.fromEntries(["m1", "sd1", "n1", "m2", "sd2", "n2"].map(k =&gt; [k, Number.isFinite(r[k]) ? r[k] : ""])), status: `Not calculated: ${r.problem}`, ...settings})
  return csvDownloadButton(columns, records, "smd_results", runAt)
}

