function orChecked(raw) {
  // reads and checks the values in the calculator. the counts must be whole numbers, and each group must have at least
  // one participant. the number of decimal places of the OR and its CI is taken from the values as typed, the fewest if
  // they differ
  const problems = []
  const clean = s =&gt; s.replace(/−/g, "-")
  const number = s =&gt; /^[-+]?(\d+\.?\d*|\.\d+)$/.test(clean(s)) ? Number(clean(s)) : NaN
  const decimals = s =&gt; s.match(/\.(\d*)$/)?.[1].length ?? 0
  const names = raw.names.map((n, i) =&gt; n || `Group ${i + 1}`)
  const cells = raw.cells.map((row, i) =&gt; row.map((c, j) =&gt; {
    const x = number(c)
    if (!Number.isInteger(x) || x &lt; 0) problems.push(`${names[i]}: the number ${j === 0 ? "with" : "without"} the event must be a whole number of 0 or more.`)
    return x
  }))
  cells.forEach((row, i) =&gt; { if (row.every(Number.isInteger) && row[0] + row[1] === 0) problems.push(`${names[i]}: the group has no participants.`) })
  const optional = (s, label) =&gt; {
    if (s === "") return null
    const x = number(s)
    if (!Number.isFinite(x)) problems.push(`The reported ${label} is not a number.`)
    return x
  }
  const p = optional(raw.p, "p-value"), or = optional(raw.or, "odds ratio"), lower = optional(raw.lower, "lower bound of the CI"), upper = optional(raw.upper, "upper bound of the CI")
  if (p !== null && (p &lt; 0 || p &gt; 1)) problems.push("The reported p-value must be between 0 and 1.")
  if ([or, lower, upper].some(x =&gt; x !== null && x &lt;= 0)) problems.push("An odds ratio and its CI must be above zero.")
  if (lower !== null && upper !== null && lower &gt;= upper) problems.push("The lower bound of the CI must be smaller than its upper bound.")
  const fewest = values =&gt; d3.min(values.filter(v =&gt; v !== ""), decimals)
  return {
    problems, names, cells, p, or, lower, upper, raw, pOp: raw.pOp,
    pDigits: p === null ? null : decimals(raw.p),
    orDigits: or === null && lower === null && upper === null ? null : fewest([raw.or, raw.lower, raw.upper])
  }
}

async function runOddsRatio(input) {
  const {webR, rVersion, recalcVersion} = await recalcR.get()
  const shelter = await new webR.Shelter()
  try {
    // the values are passed to R as vectors, never pasted into the code. values that were not entered are passed as
    // NaN, which R turns into NULL. the counts are in row order: group 1 with and without the event, then group 2
    const none = [NaN], opt = x =&gt; x === null ? none : [x]
    const res = await shelter.evalR(`
      opt &lt;- function(x) if (all(is.na(x))) NULL else x
      res &lt;- recalc_env$recalc_oddsratio(
        counts = counts, n_rows = 2, n_cols = 2,
        odds_ratio = opt(or), or_ci_lower = opt(lower), or_ci_upper = opt(upper),
        or_digits = if (is.null(opt(or_digits))) 2L else as.integer(or_digits),
        p = opt(p), p_digits = opt(p_digits), p_operator = p_operator)
      list(reproduced = as.data.frame(res$reproduced), p = as.data.frame(res$method_intervals), or = as.data.frame(res$or_results))
    `, {env: {
      counts: input.cells.flat(), or: opt(input.or), lower: opt(input.lower), upper: opt(input.upper), or_digits: opt(input.orDigits),
      p: opt(input.p), p_digits: opt(input.pDigits), p_operator: input.pOp
    }})
    const part = async name =&gt; (await res.get(name)).toD3()
    const [reproduced] = await part("reproduced")
    return {input, reproduced, pMethods: await part("p"), orRows: await part("or"), recalcVersion, rVersion, runAt: new Date()}
  } finally {
    shelter.purge()
  }
}

function orResults(run) {
  const {input, reproduced: r} = run
  const blue = "#2780e3", orange = "#d9622b"
  const finite = x =&gt; typeof x === "number" && Number.isFinite(x)
  const od = input.orDigits ?? 2
  const fmtOR = x =&gt; x.toFixed(od + 1)
  const superscript = n =&gt; `${n &lt; 0 ? "⁻" : ""}${[...String(Math.abs(n))].map(c =&gt; "⁰¹²³⁴⁵⁶⁷⁸⁹"[c]).join("")}`
  const fmtP = x =&gt; x &lt; 0.001 ? x.toExponential(1).replace(/e([-+])(\d+)/, (m, s, e) =&gt; ` × 10${superscript(s === "-" ? -e : +e)}`) : x.toFixed(4).replace(/^0\./, ".")
  const range = (values, f) =&gt; { const v = values.filter(finite); return v.length === 0 ? "cannot be calculated" : d3.min(v) === d3.max(v) ? f(v[0]) : `${f(d3.min(v))} to ${f(d3.max(v))}` }
  // with a zero count, some CI methods have no finite upper limit, which recalc returns as NA
  const unbounded = values =&gt; values.some(v =&gt; !finite(v)) ? (values.some(finite) ? ", or no finite limit" : "no finite limit") : ""
  const verdict = ok =&gt; ok === null || ok === undefined ? ["Not checked", "na"] : ok ? ["Consistent", "ok"] : ["Inconsistent", "bad"]
  const badge = ([label, kind]) =&gt; html`&lt;span class="sc-verdict sc-verdict-${kind}"&gt;${label}&lt;/span&gt;`
  const opSymbol = {equals: "=", less_than: "&lt;", greater_than: "&gt;"}[input.pOp]

  // the table and plots show the OR of group 1 relative to group 2. the verdicts also accept the reciprocal
  const asIs = run.orRows.filter(o =&gt; o.orientation === "as_is")
  const corrected = asIs.some(o =&gt; o.cc_label !== "cc:none")
  const rows = [
    {label: html`OR (${input.names[0]} vs ${input.names[1]})`, reported: input.raw.or, range: asIs.some(o =&gt; finite(o.or_unrounded)) ? range(asIs.map(o =&gt; o.or_unrounded), fmtOR) + (asIs.some(o =&gt; !finite(o.or_unrounded)) ? ", or infinite" : "") : "infinite", ok: r.or_inbounds},
    {label: "95% CI, lower bound", reported: input.raw.lower, range: range(asIs.map(o =&gt; o.ci_lower_unrounded), fmtOR), ok: r.or_ci_lower_inbounds},
    {label: "95% CI, upper bound", reported: input.raw.upper, range: asIs.some(o =&gt; finite(o.ci_upper_unrounded)) ? range(asIs.map(o =&gt; o.ci_upper_unrounded), fmtOR) + unbounded(asIs.map(o =&gt; o.ci_upper_unrounded)) : unbounded(asIs.map(o =&gt; o.ci_upper_unrounded)), ok: r.or_ci_upper_inbounds},
    {label: html`&lt;em&gt;p&lt;/em&gt;`, reported: input.p === null ? "" : `${opSymbol} ${input.raw.p}`, range: range([r.min_p, r.max_p], fmtP), ok: r.p_inbounds}
  ]

  const testNames = {pearson: "Pearson χ²", yates: "χ², Yates' correction", n1_chisq: "χ², N − 1", likelihood_ratio: "likelihood ratio", wald_z: "Wald z",
    fisher: "Fisher's exact", fisher_central: "Fisher's exact, central", fisher_midp: "Fisher's mid-p", fisher_midp_sas: "Fisher's mid-p (SAS)"}
  const estimatorNames = {uncond_mle: "sample OR", cond_mle: "conditional MLE"}
  const ciNames = {wald_logor: "Wald, log scale", cornfield_exact: "exact", midp_exact: "mid-p exact", profile_likelihood: "profile likelihood"}
  const pMethods = run.pMethods.filter(m =&gt; finite(m.p_min)).map(m =&gt; ({label: testNames[m.method] ?? m.method, lower: m.p_min, upper: m.p_max}))
  // every estimator and CI method keeps its row, so that the rows do not change from one table to another. those with
  // no finite value, which happens when a count is zero, are marked instead of drawn
  const estimates = d3.groups(asIs, o =&gt; o.estimator).map(([e, os]) =&gt; {
    const v = os.map(o =&gt; o.or_unrounded).filter(finite)
    return {label: estimatorNames[e] ?? e, lower: d3.min(v), upper: d3.max(v), open: v.length === 0}
  })
  const cis = d3.groups(asIs, o =&gt; o.ci_method).map(([m, os]) =&gt; {
    const lo = os.map(o =&gt; o.ci_lower_unrounded).filter(finite), hi = os.map(o =&gt; o.ci_upper_unrounded).filter(finite)
    return {label: ciNames[m] ?? m, lowerMin: d3.min(lo), lowerMax: d3.max(lo), upperMin: d3.min(hi), upperMax: d3.max(hi), open: hi.length &lt; os.length}
  })

  const height = n =&gt; 40 + 24 * n
  const marginLeft = items =&gt; Math.min(220, 20 + 6.5 * d3.max(items, m =&gt; m.label.length))
  const logTicks = domain =&gt; {
    // ticks at powers of ten, or also at 2 and 5 times them when the range is narrow
    const exponents = d3.range(Math.floor(Math.log10(domain[0])), Math.ceil(Math.log10(domain[1])) + 1)
    const within = v =&gt; v &gt;= domain[0] && v &lt;= domain[1]
    const powers = exponents.map(e =&gt; 10 ** e).filter(within)
    const step = Math.ceil(powers.length / 8)
    return powers.length &gt;= 3 ? powers.filter((v, i) =&gt; (powers.length - 1 - i) % step === 0) : exponents.flatMap(e =&gt; [1, 2, 5].map(k =&gt; k * 10 ** e)).filter(within)
  }
  const tickFormat = v =&gt; { const e = Math.floor(Math.log10(v) + 1e-9), k = Math.round(v / 10 ** e); return e &gt;= -3 ? String(+v.toPrecision(1)).replace(/^0\./, ".") : `${k === 1 ? "" : `${k} × `}10${superscript(e)}` }
  const ulpBand = (value, digits) =&gt; [value - 0.5 * 10 ** -digits, value + 0.5 * 10 ** -digits]
  const logPlot = (items, label, reported, bars) =&gt; {
    const values = [...items.flatMap(bars), ...reported.flat()].filter(v =&gt; finite(v) && v &gt; 0)
    const domain = [d3.min(values) / 2, d3.max(values) * 2]
    // a lower bound of exactly 0 cannot be drawn on a log scale, so it is drawn at the left edge
    const clip = v =&gt; Math.max(v, domain[0])
    return Plot.plot({
      width, height: height(items.length), marginLeft: marginLeft(items), marginRight: 20, marginBottom: 35,
      x: {type: "log", domain, ticks: logTicks(domain), tickFormat, label, labelAnchor: "center", labelOffset: 30, grid: true},
      y: {domain: items.map(m =&gt; m.label), label: null, tickSize: 0, padding: 0.3},
      style: {fontSize: "12px"},
      marks: [
        Plot.rectX(reported, {x1: d =&gt; d[0], x2: d =&gt; d[1], fill: orange, fillOpacity: 0.3}),
        ...(items[0] && "lowerMin" in items[0]
          ? [Plot.link(items.filter(m =&gt; finite(m.lowerMin)), {x1: m =&gt; clip(m.lowerMin), x2: m =&gt; clip(m.lowerMax), y1: "label", y2: "label", stroke: blue, strokeWidth: 8}),
             Plot.dot(items.filter(m =&gt; finite(m.lowerMin)), {x: m =&gt; clip(m.lowerMin), y: "label", fill: blue, r: 4}),
             Plot.link(items.filter(m =&gt; finite(m.upperMin)), {x1: "upperMin", x2: "upperMax", y1: "label", y2: "label", stroke: blue, strokeWidth: 8}),
             Plot.dot(items.filter(m =&gt; finite(m.upperMin)), {x: "upperMin", y: "label", fill: blue, r: 4}),
             Plot.text(items.filter(m =&gt; m.open), {x: domain[1], y: "label", text: () =&gt; "no upper limit →", textAnchor: "end", fill: blue, fontSize: 11})]
          : [Plot.link(items.filter(m =&gt; finite(m.lower)), {x1: m =&gt; clip(m.lower), x2: m =&gt; clip(m.upper), y1: "label", y2: "label", stroke: blue, strokeWidth: 8}),
             Plot.dot(items.filter(m =&gt; finite(m.lower)), {x: m =&gt; clip(m.lower), y: "label", fill: blue, r: 4}),
             Plot.text(items.filter(m =&gt; m.open), {x: domain[1], y: "label", text: () =&gt; "infinite →", textAnchor: "end", fill: blue, fontSize: 11})])
      ]
    })
  }
  const pReported = input.p === null ? [] : input.pOp === "equals" ? [ulpBand(input.p, input.pDigits)] : input.pOp === "less_than" ? [[1e-300, input.p]] : [[input.p, 1]]
  const orReported = input.or === null ? [] : [ulpBand(input.or, od)]
  const ciReported = [input.lower, input.upper].filter(x =&gt; x !== null).map(x =&gt; ulpBand(x, od))

  return html`&lt;div&gt;
    &lt;div class="table-responsive"&gt;&lt;table class="table table-sm sg-table"&gt;
      &lt;thead&gt;&lt;tr&gt;&lt;th&gt;&lt;/th&gt;&lt;th&gt;Reported&lt;/th&gt;&lt;th&gt;Recalculated&lt;/th&gt;&lt;th&gt;Verdict&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
      &lt;tbody&gt;${rows.map(row =&gt; html`&lt;tr&gt;&lt;td&gt;${row.label}&lt;/td&gt;&lt;td&gt;${row.reported || "–"}&lt;/td&gt;&lt;td&gt;${row.range}&lt;/td&gt;&lt;td&gt;${badge(verdict(row.ok))}&lt;/td&gt;&lt;/tr&gt;`)}&lt;/tbody&gt;
    &lt;/table&gt;&lt;/div&gt;
    ${corrected ? html`&lt;div class="sc-status sg-note"&gt;One of the counts is zero, so the odds in one group are zero and the OR is infinite (or zero, with the groups the other way round). The sample OR can only be calculated after adding 0.5 to every cell, as was done here. The conditional estimate stays infinite, and the exact, mid-p, and profile likelihood intervals have no finite upper limit.&lt;/div&gt;` : ""}
    &lt;div class="sg-plot"&gt;&lt;div class="sg-plot-title"&gt;&lt;em&gt;p&lt;/em&gt;-value, by test&lt;/div&gt;${logPlot(pMethods, "p-value (log scale)", pReported, m =&gt; [m.lower, m.upper])}&lt;/div&gt;
    ${estimates.some(m =&gt; !m.open) ? html`&lt;div class="sg-plot"&gt;&lt;div class="sg-plot-title"&gt;Odds ratio, by estimator&lt;/div&gt;${logPlot(estimates, "odds ratio (log scale)", orReported, m =&gt; [m.lower, m.upper])}&lt;/div&gt;` : ""}
    ${cis.some(c =&gt; finite(c.lowerMin)) ? html`&lt;div class="sg-plot"&gt;&lt;div class="sg-plot-title"&gt;95% CI of the odds ratio, by method&lt;/div&gt;${logPlot(cis, "odds ratio (log scale)", ciReported, m =&gt; [m.lowerMin, m.lowerMax, m.upperMin, m.upperMax])}&lt;/div&gt;` : ""}
    &lt;div class="sc-status"&gt;Blue is what each method produces from the counts, and orange is the reported value, as the range of values that round to it (or, for &lt;em&gt;p&lt;/em&gt; &lt; and &lt;em&gt;p&lt;/em&gt; &gt;, the values it allows). In the CI plot, each row has the lower and the upper bound, across both estimators. The OR is that of ${input.names[0]} relative to ${input.names[1]}; a reported OR or CI is also counted as consistent if it matches with the groups the other way round.&lt;/div&gt;
    &lt;div class="sc-status"&gt;Calculated by &lt;code&gt;recalc_oddsratio()&lt;/code&gt; from recalc ${run.recalcVersion} (commit &lt;a href="https://github.com/ianhussey/recalc/tree/${recalcCommit}"&gt;${recalcCommit.slice(0, 7)}&lt;/a&gt;), ${run.rVersion}, running in webR ${webrVersion}. The counts were taken as exact${input.orDigits === null ? "" : `, the OR and its CI as rounded to ${input.orDigits} decimal place${input.orDigits === 1 ? "" : "s"}`}${input.pDigits === null ? "" : `, and the p-value to ${input.pDigits}`}.&lt;/div&gt;
    &lt;div class="sb-buttons sc-download"&gt;${orDownloadButton(run, rows, verdict)}&lt;/div&gt;
  &lt;/div&gt;`
}

